import { FormEvent, useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import worldMapImage from './assets/mapa-mundi-interativo-3d.png'
import helenaPortrait from './assets/dra-helena-rocha.png'
import rafaelPortrait from './assets/dr-rafael-nunes.png'
import camilaPortrait from './assets/dra-camila-torres.png'
import andrePortrait from './assets/dr-andre-lima.png'
import ninaAssistant from './assets/nina-assistente.png'
import operationScenes from './assets/cenarios-operacao.png'
import mahanOperation from './assets/porto-mahan-operacao.png'
import { dailyDispatches, missions, team, type Clue, type CycleEvent, type Intervention, type Mission, type Role } from './data/missions'
import './styles.css'

type Phase = 'investigation' | 'containment' | 'won' | 'lost'
type Modal = 'briefing' | 'reveal' | 'diagnosis' | 'advance' | 'complete' | 'event' | 'wrong' | 'win' | 'lost' | 'feedback' | null
type MissionAct = 'proteger' | 'investigar' | 'decidir' | 'controlar' | 'resultado'
type Student = { name: string; semester: string; focus: string }
type Reveal = Clue | Intervention
type Area = 'investigacao' | 'conduta' | 'controle' | 'tempo' | 'diagnostico'
type Log = { id: string; area: Area; title: string; note: string; tone: 'good' | 'warn' | 'neutral' }
type Player = { playerId: string; xp: number; coins: number; completed: number[]; dailyClaimed: string; lastActiveDay: string; streak: number }
type ActiveGame = { missionId: number; cycle: number; actions: number; cases: number; care: number; resources: number; clueIds: string[]; interventionIds: string[]; logs: Log[]; urgentCare: boolean; pendingLabId: string | null; phase: Extract<Phase, 'investigation' | 'containment'>; dailyMission: boolean }

const focusLabels: Record<string, string> = { clinica: 'raciocínio clínico', microbiologia: 'microbiologia', epidemiologia: 'epidemiologia', saudeColetiva: 'saúde coletiva' }
const shuffled = <T,>(items: T[]) => [...items].sort(() => Math.random() - .5)
const portraits: Record<Role, string> = { emergencia: helenaPortrait, infectologia: rafaelPortrait, epidemiologia: camilaPortrait, laboratorio: andrePortrait }
const localDay = () => new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' })
const dayBefore = (day: string) => { const [year, month, date] = day.split('-').map(Number); return new Date(Date.UTC(year, month - 1, date - 1)).toISOString().slice(0, 10) }
const newPlayer = (): Player => ({ playerId: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : `local-${Date.now()}-${Math.random().toString(16).slice(2)}`, xp: 0, coins: 0, completed: [], dailyClaimed: '', lastActiveDay: '', streak: 0 })

function App() {
  const [student, setStudent] = useState<Student | null>(() => { try { return JSON.parse(localStorage.getItem('missao-imunidade-estudante') || 'null') } catch { return null } })
  const [editing, setEditing] = useState(false)
  const [tutorial, setTutorial] = useState(() => localStorage.getItem('missao-imunidade-tutorial-v3') !== 'true')
  const [missionId, setMissionId] = useState<number | null>(null)
  const [player, setPlayer] = useState<Player>(() => { try { const value = JSON.parse(localStorage.getItem('missao-imunidade-jogador-v1') || 'null'); return value?.playerId ? { ...newPlayer(), ...value, streak: Number.isInteger(value.streak) ? value.streak : 0 } : newPlayer() } catch { return newPlayer() } })
  const [lastReward, setLastReward] = useState(0)
  const [testMode] = useState(() => new URLSearchParams(window.location.search).has('teste'))
  const [cycle, setCycle] = useState(1)
  const [actions, setActions] = useState(3)
  const [cases, setCases] = useState(0)
  const [care, setCare] = useState(100)
  const [resources, setResources] = useState(5)
  const [clues, setClues] = useState<Clue[]>([])
  const [interventions, setInterventions] = useState<Intervention[]>([])
  const [logs, setLogs] = useState<Log[]>([])
  const [urgentCare, setUrgentCare] = useState(false)
  const [pendingLab, setPendingLab] = useState<Clue | null>(null)
  const [phase, setPhase] = useState<Phase>('investigation')
  const [modal, setModal] = useState<Modal>(null)
  const [reveal, setReveal] = useState<Reveal | null>(null)
  const [eventOption, setEventOption] = useState<CycleEvent['options'][number] | null>(null)
  const [diagnosis, setDiagnosis] = useState('')
  const [rationale, setRationale] = useState('')
  const [diagnosticError, setDiagnosticError] = useState('')
  const [diagnosesOrder, setDiagnosesOrder] = useState<string[]>([])
  const [rationaleOrder, setRationaleOrder] = useState<Mission['diagnosticCheck']['options']>([])
  const [eventOrder, setEventOrder] = useState<CycleEvent['options']>([])
  const [dailyMission, setDailyMission] = useState(false)
  const [guideDismissed, setGuideDismissed] = useState(false)

  useEffect(() => { if (student) localStorage.setItem('missao-imunidade-estudante', JSON.stringify(student)) }, [student])
  useEffect(() => { localStorage.setItem('missao-imunidade-jogador-v1', JSON.stringify(player)); void fetch('/api/progress', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(player) }).catch(() => undefined) }, [player])
  useEffect(() => { void fetch(`/api/progress/${player.playerId}`).then((response) => response.ok ? response.json() : null).then((saved: Player | null) => { if (saved) setPlayer((current) => ({ ...current, xp: Math.max(current.xp, saved.xp), coins: Math.max(current.coins, saved.coins), completed: [...new Set([...current.completed, ...saved.completed])], dailyClaimed: saved.dailyClaimed || current.dailyClaimed, lastActiveDay: saved.lastActiveDay || current.lastActiveDay, streak: Math.max(current.streak, saved.streak || 0) })) }).catch(() => undefined) }, [player.playerId])
  useEffect(() => { try { const saved = JSON.parse(localStorage.getItem('missao-imunidade-partida-v1') || 'null') as ActiveGame | null; const savedMission = saved && missions.find((item) => item.id === saved.missionId); if (!saved || !savedMission) return; const allClues = Object.values(savedMission.clues).flat(); setMissionId(savedMission.id); setCycle(saved.cycle); setActions(saved.actions); setCases(saved.cases); setCare(saved.care); setResources(saved.resources); setClues(allClues.filter((item) => saved.clueIds.includes(item.id))); setInterventions(savedMission.interventions.filter((item) => saved.interventionIds.includes(item.id))); setLogs(saved.logs || []); setUrgentCare(saved.urgentCare); setPendingLab(allClues.find((item) => item.id === saved.pendingLabId) || null); setPhase(saved.phase); setDailyMission(saved.dailyMission); setDiagnosesOrder(shuffled(savedMission.diagnoses)); setRationaleOrder(shuffled(savedMission.diagnosticCheck.options)) } catch { localStorage.removeItem('missao-imunidade-partida-v1') } }, [])
  useEffect(() => { if (!missionId || phase === 'won' || phase === 'lost') { if (phase === 'won' || phase === 'lost') localStorage.removeItem('missao-imunidade-partida-v1'); return } const activeMission = missions.find((item) => item.id === missionId); if (!activeMission) return; const value: ActiveGame = { missionId, cycle, actions, cases, care, resources, clueIds: clues.map((item) => item.id), interventionIds: interventions.map((item) => item.id), logs, urgentCare, pendingLabId: pendingLab?.id || null, phase, dailyMission }; localStorage.setItem('missao-imunidade-partida-v1', JSON.stringify(value)) }, [missionId, cycle, actions, cases, care, resources, clues, interventions, logs, urgentCare, pendingLab, phase, dailyMission])
  useEffect(() => { setGuideDismissed(false) }, [actions, phase, urgentCare, clues.length])
  const closeTutorial = () => { localStorage.setItem('missao-imunidade-tutorial-v3', 'true'); setTutorial(false) }
  const mission = missions.find((item) => item.id === missionId)
  const foundIds = useMemo(() => new Set(clues.map((item) => item.id)), [clues])
  const interventionIds = useMemo(() => new Set(interventions.map((item) => item.id)), [interventions])
  const addLog = (entry: Log) => setLogs((previous) => [...previous, entry])
  const start = (item: Mission, isDaily = false) => {
    localStorage.removeItem('missao-imunidade-partida-v1')
    setDailyMission(isDaily)
    setMissionId(item.id); setCycle(1); setActions(3); setCases(item.initialCases); setCare(100); setResources(5); setClues([]); setInterventions([]); setLogs([]); setUrgentCare(false); setPendingLab(null); setPhase('investigation'); setReveal(null); setEventOption(null); setDiagnosis(''); setRationale(''); setDiagnosesOrder(shuffled(item.diagnoses)); setRationaleOrder(shuffled(item.diagnosticCheck.options)); setModal('briefing')
  }
  if (!student || editing) return <Profile initial={student || undefined} onSave={(value) => { setStudent(value); setEditing(false) }} />
  const completed = player.completed
  if (!mission) return <Campaign student={student} player={player} completed={completed} testMode={testMode} tutorial={tutorial} onTutorial={() => setTutorial(true)} onCloseTutorial={closeTutorial} onEdit={() => setEditing(true)} onStart={start} />

  const pilot = mission.id === 1
  const inContainment = phase === 'containment'
  const finished = phase === 'won' || phase === 'lost'
  const total = Object.values(mission.clues).flat().length
  const alert = cases < mission.initialCases * 2.5 ? 'Moderado' : cases < mission.initialCases * 7 ? 'Alto' : 'Crítico'
  const requiredComplete = mission.requiredInterventions.every((id) => interventionIds.has(id))
  const cycleEvent = mission.cycleEvents[(cycle - 1) % mission.cycleEvents.length]
  const baseProjected = Math.round(cases * (inContainment ? mission.containmentGrowth : mission.investigationGrowth))
  const projected = eventOption ? Math.round(baseProjected * eventOption.pressureFactor) : baseProjected
  const advance = () => {
    if (!eventOption) return
    const nextCases = projected; const nextCycle = cycle + 1
    setCases(nextCases); setCycle(nextCycle); setActions(3); setResources((value) => Math.min(6, value + 1)); setReveal(null); setEventOption(null)
    if (!urgentCare) { setCare((value) => Math.min(100, value + 18)); addLog({ id: `priority-delay-${cycle}`, area: 'conduta', title: `${mission.priorityAction.metricLabel} ficou sob pressão`, note: 'A prioridade inicial não foi acionada antes do fechamento do ciclo.', tone: 'warn' }) }
    if (nextCases >= mission.maxCases || nextCycle > mission.maxDays) { setPhase('lost'); setModal('lost'); return }
    if (pendingLab) { const result = pendingLab; setPendingLab(null); setClues((current) => [...current, result]); setReveal(result); setModal('reveal'); addLog({ id: `lab-result-${result.id}`, area: 'investigacao', title: 'Resultado liberado', note: 'Você planejou o prazo do laboratório e recebeu o laudo no ciclo seguinte.', tone: 'good' }) } else setModal(null)
  }
  const closeReveal = () => { setReveal(null); setModal(actions === 0 ? 'complete' : null) }
  const investigate = (role: Role) => {
    const clue = mission.clues[role].find((item) => !foundIds.has(item.id) && item.id !== pendingLab?.id)
    const cost = role === 'laboratorio' ? 2 : 1
    if (!clue || !actions || resources < cost) return
    setActions((value) => value - 1)
    setResources((value) => value - cost)
    if (role === 'laboratorio') {
      setPendingLab(clue); setReveal({ id: 'lab-pending', role: 'laboratorio', category: 'Laboratório', level: 1, title: 'Exame encaminhado', text: 'A amostra foi enviada. O resultado será liberado no próximo ciclo; enquanto isso, sua equipe pode continuar o cuidado e a investigação.' }); setModal('reveal'); addLog({ id: `lab-request-${clue.id}`, area: 'investigacao', title: 'Exame solicitado com propósito', note: 'Você usou 2 recursos para reduzir uma incerteza diagnóstica.', tone: 'good' }); return
    }
    setClues((current) => [...current, clue]); setReveal(clue); setModal('reveal'); addLog({ id: `clue-${clue.id}`, area: 'investigacao', title: `Investigação: ${clue.category}`, note: `A equipe registrou “${clue.title}”.`, tone: 'neutral' })
  }
  const stabilize = () => {
    if (urgentCare || !actions || resources < 1) return
    setActions((value) => value - 1); setResources((value) => value - 1); setUrgentCare(true); setCare(58)
    const item: Intervention = { id: `priority-${mission.id}`, icon: '✦', label: mission.priorityAction.label, title: mission.priorityAction.title, text: mission.priorityAction.text, tone: 'orange', factor: 1, teachingNote: 'Em uma simulação educativa, a primeira resposta pode proteger pessoas enquanto a equipe ainda reduz a incerteza diagnóstica.' }
    setReveal(item); setModal('reveal'); addLog({ id: `priority-${mission.id}`, area: 'conduta', title: mission.priorityAction.completion, note: 'Você acionou uma prioridade operacional antes da confirmação etiológica.', tone: 'good' })
  }
  const contain = (item: Intervention) => {
    if (!actions || interventionIds.has(item.id)) return
    const next = [...interventions, item]; setActions((value) => value - 1); setInterventions(next); setCases((value) => Math.max(1, Math.round(value * item.factor))); addLog({ id: `intervention-${item.id}`, area: 'controle', title: `Resposta: ${item.title}`, note: mission.requiredInterventions.includes(item.id) ? 'Medida prioritária para o cenário foi aplicada.' : 'Medida complementar fortaleceu a resposta.', tone: mission.requiredInterventions.includes(item.id) ? 'good' : 'neutral' })
    if (mission.requiredInterventions.every((id) => next.some((entry) => entry.id === id)) && next.length >= 3) { const reward = Math.max(180, 520 - (cycle - 1) * 35); const today = localDay(); const dailyBonus = dailyMission && player.dailyClaimed !== today; const newMission = !player.completed.includes(mission.id); const totalReward = (newMission ? reward : 0) + (dailyBonus ? 80 : 0); setPhase('won'); setPlayer((current) => { const claimToday = dailyMission && current.dailyClaimed !== today; const nextStreak = claimToday ? (current.lastActiveDay === dayBefore(today) ? current.streak + 1 : 1) : current.streak; return { ...current, xp: current.xp + (!current.completed.includes(mission.id) ? reward : 0) + (claimToday ? 80 : 0), coins: current.coins + (!current.completed.includes(mission.id) ? 25 : 0) + (claimToday ? 15 : 0), completed: current.completed.includes(mission.id) ? current.completed : [...current.completed, mission.id], dailyClaimed: claimToday ? today : current.dailyClaimed, lastActiveDay: claimToday ? today : current.lastActiveDay, streak: nextStreak } }); setLastReward(totalReward); setModal('win') } else { setReveal(item); setModal('reveal') }
  }
  const confirmDiagnosis = () => {
    if (!diagnosis || !rationale) return
    const robust = clues.length >= 3 && new Set(clues.map((item) => item.role)).size >= 2
    if (diagnosis === mission.disease && rationale === mission.diagnosticCheck.correctId && robust) { const labSupported = clues.some((item) => item.role === 'laboratorio'); setPhase('containment'); setActions(3); setReveal({ id: 'confirmed', role: labSupported ? 'laboratorio' : 'infectologia', category: labSupported ? 'Laboratório' : 'Vigilância', level: 2, title: labSupported ? 'Hipótese confirmada com apoio laboratorial' : 'Hipótese bem fundamentada', text: labSupported ? 'Sua defesa conectou mais de uma lente de investigação e recebeu apoio do laboratório. Agora coordene a resposta proporcional ao cenário.' : 'Sua defesa conectou mais de uma lente de investigação. Ela orienta a resposta enquanto a confirmação laboratorial não está disponível.' }); setModal('reveal'); addLog({ id: 'diagnosis-confirmed', area: 'diagnostico', title: labSupported ? 'Hipótese confirmada com apoio laboratorial' : 'Hipótese bem defendida', note: 'O diagnóstico e a evidência discriminativa foram conectados a mais de uma lente.', tone: 'good' }); return }
    const message = !robust ? 'A hipótese precisa de pelo menos duas lentes de investigação. Uma pista isolada não sustenta uma resposta coletiva.' : diagnosis === mission.disease ? 'A hipótese foi nomeada corretamente, mas o dado escolhido não é o mais discriminativo.' : 'Essa hipótese ainda não explica melhor o conjunto. Retome cronologia, padrão clínico, exposição e laboratório.'
    setDiagnosticError(message); const nextCases = Math.round(cases * mission.investigationGrowth); const nextCycle = cycle + 1; setCases(nextCases); setCycle(nextCycle); setActions(3); setModal(nextCases >= mission.maxCases || nextCycle > mission.maxDays ? 'lost' : 'wrong'); if (nextCases >= mission.maxCases || nextCycle > mission.maxDays) setPhase('lost'); addLog({ id: `diagnosis-${cycle}`, area: 'diagnostico', title: 'Defesa precisa ser revisada', note: message, tone: 'warn' })
  }
  const score = Math.max(1500, 7000 - (cycle - 1) * 450 - Math.max(0, 4 - clues.length) * 180 + (urgentCare ? 250 : 0))
  const phaseName = finished ? 'ENCERRADA' : inContainment ? 'RESPOSTA' : 'INVESTIGAÇÃO'
  const evidenceNeeded = Math.max(0, 3 - clues.length)
  const cycleCloseLabel = actions === 1 ? 'Fechar ciclo com 1 decisão não usada' : `Fechar ciclo com ${actions} decisões não usadas`
  const reset = () => start(mission, dailyMission)
  const closeModal = () => setModal(null)
  const missionAct = finished ? 'resultado' : inContainment ? 'controlar' : !urgentCare ? 'proteger' : clues.length < 3 ? 'investigar' : 'decidir'
  return <main className="game-shell">
    <header className="topbar"><button className="brand brand-button" onClick={() => { setMissionId(null); setModal(null) }}><span className="brand-mark">✦</span><span>MISSÃO <b>IMUNIDADE</b></span></button><div className="mission-chip"><span>{mission.caseCode.toUpperCase()}</span><strong>{mission.shortName}</strong></div><div className="phase-chip"><span>ETAPA</span><strong>{inContainment ? 'Resposta' : phase === 'investigation' ? 'Investigação' : 'Encerrada'}</strong></div><button className="mission-help" onClick={() => setTutorial(true)}>Como jogar</button><PlayerHud player={player} compact /><div className="day-chip"><span>Ciclo</span><strong>{cycle}</strong></div></header>
    <section className="command-strip"><div className="cycle-state"><span className="pulse-dot" /><div><small>{finished ? 'MISSÃO ENCERRADA' : `CICLO ${cycle} · ${phaseName}`}</small><strong>{finished ? 'Consulte seu debriefing' : `${actions} ${actions === 1 ? 'decisão restante' : 'decisões restantes'}`}</strong></div></div><div className="case-state"><span><small>CASOS ATIVOS</small><b>{cases}</b></span><span><small>PRESSÃO</small><b className={`alert ${alert.toLowerCase()}`}>{alert}</b></span></div>{phase === 'investigation' && <button id="diagnosis-action" className={`diagnose-button ${urgentCare && clues.length >= 3 ? 'guide-target' : ''}`} disabled={clues.length < 3} onClick={() => setModal('diagnosis')}>Defender hipótese <small>{evidenceNeeded ? `${evidenceNeeded === 1 ? 'falta' : 'faltam'} ${evidenceNeeded} ${evidenceNeeded === 1 ? 'evidência' : 'evidências'}` : 'pronto para argumentar'}</small></button>}</section>
    <MissionSteps act={missionAct} />
    <section className="mission-metrics" aria-label="Situação operacional"><div><span>⚕</span><small>{mission.priorityAction.metricLabel}</small><b className={care > 75 ? 'metric-danger' : ''}>{care > 75 ? mission.priorityAction.before : mission.priorityAction.after}</b></div><div><span>◈</span><small>RECURSOS</small><b>{resources}/6</b></div><div><span>⌛</span><small>EXAME</small><b>{pendingLab ? 'próximo ciclo' : 'nenhum pendente'}</b></div><p>Indicadores são uma simulação educativa. Mais casos identificados podem significar melhor vigilância.</p></section>
    {!finished && <section className="cycle-guide"><div><span>SEU OBJETIVO AGORA</span><b>{inContainment ? 'Aplique três medidas, incluindo as duas prioritárias.' : !urgentCare ? `${mission.priorityAction.action} antes de aprofundar a investigação.` : 'Combine lentes diferentes antes de defender uma hipótese.'}</b></div>{actions > 0 && <button onClick={() => setModal('advance')}>{cycleCloseLabel}</button>}</section>}
    {!finished && !guideDismissed && <GameGuide phase={phase} urgentCare={urgentCare} clueCount={clues.length} onDismiss={() => setGuideDismissed(true)} />}
    <section className="dashboard pilot-dashboard">{pilot ? <MissionScene urgentCare={urgentCare} pendingLab={Boolean(pendingLab)} act={missionAct} /> : <OperationScene mission={mission} urgentCare={urgentCare} pendingLab={Boolean(pendingLab)} act={missionAct} />}<Board mission={mission} clues={clues} interventions={interventions} inContainment={inContainment} finished={finished} labConfirmed={clues.some((item) => item.role === 'laboratorio')} requiredComplete={requiredComplete} total={total} logs={logs} /></section>
    {phase === 'investigation' && <section className={`case-file ${pilot ? 'pilot-brief' : ''}`}><span className="eyebrow">{pilot ? 'CHAMADO DE CAMPO' : 'DADOS DISPONÍVEIS AO PLANTÃO'}</span><h2>{mission.openingSyndrome}</h2><details><summary>Ver contexto do chamado</summary><p>{mission.brief}</p></details><div>{mission.initialData.map((item) => <span key={item.label}>{item.label}<b>{item.value}</b></span>)}</div></section>}
    <section className={`team-section act-${missionAct}`}>{missionAct === 'decidir' && <article className="decision-gate"><span>🧩 MOMENTO DE DECISÃO</span><h3>Você já reuniu pistas suficientes.</h3><p>Conecte o que observou e defenda a hipótese que melhor explica o conjunto.</p><button className="primary" onClick={() => setModal('diagnosis')}>Defender hipótese →</button></article>}<div className="team-heading"><div><span className="eyebrow">{finished ? 'RESULTADO DA MISSÃO' : inContainment ? 'PROTOCOLO DE RESPOSTA' : 'PRÓXIMA DECISÃO'}</span><h2>{finished ? 'Caso encerrado' : inContainment ? 'Escolha uma medida para a resposta' : 'Quem sua central aciona agora?'}</h2></div><div className="action-counter"><b>{finished ? '✓' : actions}</b> {finished ? 'debriefing disponível' : 'decisões neste ciclo'}</div></div>{phase === 'investigation' && <><div id="team-missions" className={`mission-instruction ${urgentCare && clues.length < 3 ? 'guide-target' : ''}`}><b>ESCOLHA UMA MISSÃO</b><span>Você tem {actions} ações e {resources} recursos. O laboratório custa 2 recursos e libera o resultado no próximo ciclo.</span></div><article id="care-priority" className={`urgent-card ${urgentCare ? 'used' : ''} ${!urgentCare ? 'guide-target' : ''}`}><img src={helenaPortrait} alt="Dra. Helena Rocha" /><div><span>{mission.priorityAction.label} · CENTRAL</span><h3>{mission.priorityAction.title}</h3><p>{mission.priorityAction.text}</p></div><button onClick={stabilize} disabled={urgentCare || !actions || resources < 1}>{urgentCare ? mission.priorityAction.completion : mission.priorityAction.action} →</button></article><div className={`team-grid ${urgentCare && clues.length < 3 ? 'guide-team-grid' : ''}`}>{team.map((member) => { const roleClues = mission.clues[member.role]; const done = roleClues.filter((clue) => foundIds.has(clue.id)).length; const next = roleClues.find((clue) => !foundIds.has(clue.id) && clue.id !== pendingLab?.id); const labPending = member.role === 'laboratorio' && Boolean(pendingLab); const cost = member.role === 'laboratorio' ? 2 : 1; return <article className={`member-card ${member.tone} ${done === 2 ? 'used' : ''}`} key={member.role}><img className="team-portrait" src={portraits[member.role]} alt={member.name} /><div className="member-info"><span>{member.specialty}</span><h3>{member.name}</h3><p>{labPending ? 'Exame em processamento · resultado no próximo ciclo' : next ? `Missão: ${next.title}` : 'Eixo investigado por completo'}</p></div><button onClick={() => investigate(member.role)} disabled={!next || !actions || labPending || resources < cost}>{next ? `${member.action} · ${cost} recurso${cost > 1 ? 's' : ''}` : 'Eixo concluído'}<span>→</span></button></article> })}</div></>}{inContainment && <div id="response-actions" className="team-grid containment-grid">{mission.interventions.map((item) => { const used = interventionIds.has(item.id); const essential = mission.requiredInterventions.includes(item.id); return <article className={`member-card ${item.tone} ${used ? 'used' : ''}`} key={item.id}><div className="member-icon">{item.icon}</div><div className="member-info"><span>{item.label} · {essential ? 'prioritária' : 'complementar'}</span><h3>{item.title}</h3><p>{item.text}</p></div><button onClick={() => contain(item)} disabled={used || !actions}>{used ? 'Medida aplicada' : 'Aplicar medida'}<span>→</span></button></article> })}</div>}<div className="mobile-board"><Board mission={mission} clues={clues} interventions={interventions} inContainment={inContainment} finished={finished} labConfirmed={clues.some((item) => item.role === 'laboratorio')} requiredComplete={requiredComplete} total={total} logs={logs} /></div>{finished && <div className="finished-actions"><p>{phase === 'won' ? 'Caso concluído. Consulte o debriefing da sua partida.' : 'A pressão do cenário ultrapassou o limite. Use o debriefing para revisar sua estratégia.'}</p><div><button className="secondary" onClick={() => setModal(phase === 'won' ? 'win' : 'lost')}>Ver debriefing</button><button className="primary" onClick={reset}>Reiniciar caso</button></div></div>}</section>
    <Dialogs modal={modal} mission={mission} cycle={cycle} actions={actions} cases={cases} baseProjected={baseProjected} projected={projected} event={cycleEvent} eventOption={eventOption} eventOptions={eventOrder.length ? eventOrder : cycleEvent.options} clues={clues.length} diagnosis={diagnosis} rationale={rationale} diagnoses={diagnosesOrder} rationaleOptions={rationaleOrder} error={diagnosticError} reveal={reveal} outcome={phase === 'won' ? 'vitória' : 'tentativa interrompida'} score={score} reward={lastReward} logs={logs} onClose={closeModal} onCloseReveal={closeReveal} onSelectDiagnosis={setDiagnosis} onSelectRationale={setRationale} onConfirm={confirmDiagnosis} onShowEvent={() => { setEventOption(null); setEventOrder(shuffled(cycleEvent.options)); setModal('event') }} onSelectEventOption={setEventOption} onAdvance={advance} onFeedback={() => setModal('feedback')} onReset={reset} onCampaign={() => { setMissionId(null); setModal(null) }} />
    {tutorial && <Tutorial onClose={closeTutorial} />}
  </main>
}

function PlayerHud({ player, compact = false }: { player: Player; compact?: boolean }) { const level = Math.floor(player.xp / 700) + 1; const progress = player.xp % 700; return <div className={`player-hud ${compact ? 'compact' : ''}`} aria-label={`Nível ${level}, ${player.xp} XP e ${player.coins} moedas`}><div className="player-avatar">✦<span>{level}</span></div><div className="player-level"><small>NÍVEL {level}</small><div><i style={{ width: `${Math.max(5, progress / 7)}%` }} /></div><b>{progress}/700 XP</b></div><div className="player-coins">◉ <b>{player.coins}</b></div></div> }

function Map({ mission, inContainment }: { mission: Mission; inContainment: boolean }) { return <div className="map-panel panel"><div className="panel-heading"><div><span className="eyebrow">{mission.caseCode.toUpperCase()} · AGENTE NÃO REVELADO</span><h1>Foco do <em>caso</em></h1></div><span className="live">● AO VIVO</span></div><div className="world-map"><img src={worldMapImage} alt="Mapa-múndi ilustrativo" /><div className={`focus-line ${inContainment ? 'contained' : ''}`} style={{ left: `${mission.mapPosition.x}%`, top: `${mission.mapPosition.y}%` }} /><div className={`outbreak-pin ${inContainment ? 'contained' : ''}`} style={{ left: `${mission.mapPosition.x}%`, top: `${mission.mapPosition.y}%` }}><span className="pin-ring" /><span className="pin-core" /><div className="pin-label"><b>{inContainment ? 'RESPOSTA ATIVA' : 'FOCO EM ANÁLISE'}</b><br />{mission.location}</div></div><div className="map-scan" /></div><div className="map-footer"><span>{mission.region} · {mission.location}</span></div></div> }

function MissionScene({ urgentCare, pendingLab, act }: { urgentCare: boolean; pendingLab: boolean; act: MissionAct }) {
  const voice = pendingLab ? { image: andrePortrait, name: 'Dr. André', text: 'A amostra está a caminho do laboratório. Use o ciclo para cruzar cuidado, exposição e vigilância.' } : act === 'proteger' ? { image: helenaPortrait, name: 'Dra. Helena', text: 'A enchente trouxe pacientes desidratados. Acione o cuidado imediato antes de procurar a resposta.' } : act === 'investigar' ? { image: camilaPortrait, name: 'Dra. Camila', text: 'Agora escolha uma lente. Cada personagem revela uma parte diferente do mapa do surto.' } : act === 'decidir' ? { image: rafaelPortrait, name: 'Dr. Rafael', text: 'As pistas já conversam entre si. Junte o padrão clínico e a exposição antes de defender sua hipótese.' } : urgentCare ? { image: helenaPortrait, name: 'Dra. Helena', text: 'O ponto de reidratação está ativo. Agora transforme a hipótese em medidas de controle.' } : { image: helenaPortrait, name: 'Central', text: 'A equipe está pronta para o próximo passo.' }
  return <section className="mission-scene mahan-scene panel" aria-label="Central de comando de Porto de Mahan"><div className="scene-mahan-art" style={{ backgroundImage: `url(${mahanOperation})` }} /><div className="scene-grid" /><div className="scene-header"><span>OPERAÇÃO MARÉ SEGURA</span><b>PORTO DE MAHAN</b></div><div className="scene-portraits"><img src={helenaPortrait} alt="Dra. Helena Rocha" /><img src={rafaelPortrait} alt="Dr. Rafael Nunes" /><img src={camilaPortrait} alt="Dra. Camila Torres" /><img src={andrePortrait} alt="Dr. André Lima" /></div><div className="scene-dialogue"><div className="scene-avatar"><img src={voice.image} alt="" /></div><p><b>{voice.name}:</b> {voice.text}</p></div><div className="scene-objective"><span>OBJETIVO</span><b>Proteger vidas e interromper a exposição.</b></div></section>
}

function OperationScene({ mission, urgentCare, pendingLab, act }: { mission: Mission; urgentCare: boolean; pendingLab: boolean; act: MissionAct }) {
  const sceneIndex = Math.max(0, mission.id - 2)
  const labels = ['OPERAÇÃO VETOR EM ALERTA', 'OPERAÇÃO REDE PROTEGIDA', 'OPERAÇÃO AR SEGURO', 'OPERAÇÃO BARREIRA ATIVA']
  const voice = pendingLab ? { image: andrePortrait, name: 'Dr. André', text: 'O exame está em processamento. Use este ciclo para cruzar clínica, território e vigilância.' } : act === 'proteger' ? { image: helenaPortrait, name: 'Dra. Helena', text: `${mission.priorityAction.title}. Esta é a primeira ordem da central.` } : act === 'investigar' ? { image: camilaPortrait, name: 'Dra. Camila', text: 'Escolha um personagem. Toda pista nova reduz uma dúvida diferente.' } : act === 'decidir' ? { image: rafaelPortrait, name: 'Dr. Rafael', text: 'Chegou a hora de conectar as pistas e defender a hipótese mais forte.' } : urgentCare ? { image: helenaPortrait, name: 'Dra. Helena', text: 'A proteção inicial está ativa. Agora escolha medidas para reduzir novas exposições.' } : { image: helenaPortrait, name: 'Central', text: 'A equipe aguarda a próxima ordem.' }
  return <section className={`mission-scene operation-scene scene-${sceneIndex} panel`} aria-label={`Central de comando de ${mission.shortName}`}><div className="scene-grid" /><div className="operation-scene-art" style={{ backgroundImage: `url(${operationScenes})` }} /><div className="scene-header"><span>{labels[sceneIndex]}</span><b>{mission.shortName.toUpperCase()}</b></div><div className="operation-alert"><span>⚡ AGORA</span><b>{act === 'proteger' ? mission.priorityAction.action : act === 'investigar' ? 'Escolha uma lente' : act === 'decidir' ? 'Defenda a hipótese' : 'Aplique a resposta'}</b></div><div className="scene-portraits operation-portraits"><img src={helenaPortrait} alt="Dra. Helena Rocha" /><img src={rafaelPortrait} alt="Dr. Rafael Nunes" /><img src={camilaPortrait} alt="Dra. Camila Torres" /><img src={andrePortrait} alt="Dr. André Lima" /></div><div className="scene-dialogue"><div className="scene-avatar"><img src={voice.image} alt="" /></div><p><b>{voice.name}:</b> {voice.text}</p></div><div className="scene-objective"><span>OBJETIVO</span><b>{mission.priorityAction.text}</b></div></section>
}

function Board({ mission, clues, interventions, inContainment, finished, labConfirmed, requiredComplete, total, logs }: { mission: Mission; clues: Clue[]; interventions: Intervention[]; inContainment: boolean; finished: boolean; labConfirmed: boolean; requiredComplete: boolean; total: number; logs: Log[] }) { const guidance = finished ? 'Caso encerrado. Abra o debriefing para revisar suas decisões.' : clues.length === 0 ? 'Escolha uma frente para registrar o primeiro achado.' : clues.length < 3 ? 'Cruze esta descoberta com outra lente antes de concluir.' : clues.length < 6 ? 'Você já pode defender uma hipótese; investigue mais se ainda houver dúvida.' : 'Seu dossiê está robusto. Pese as evidências.'; return <aside className="intel-panel panel evidence-board"><div className="intel-heading"><div><span className="eyebrow">QUADRO DO CASO</span><h2>{finished ? 'Caso encerrado' : inContainment ? 'Resposta em andamento' : 'Evidências reunidas'}</h2></div><span>{finished ? '✓' : inContainment ? `${interventions.length}/4` : `${clues.length}/${total}`}</span></div>{!inContainment && <div className="lens-progress">{team.map((member) => { const count = clues.filter((item) => item.role === member.role).length; return <div key={member.role} className={count ? `active ${member.tone}` : ''}><span>{member.icon}</span><b>{count}/2</b><small>{member.specialty.replace('Medicina de ', '')}</small></div> })}</div>}<div className="evidence-list">{!inContainment && !clues.length && <div className="empty-state"><span>⌁</span><p>{guidance}</p></div>}{!inContainment && clues.map((clue) => <article className="evidence-card" key={clue.id}><span>{clue.category} · camada {clue.level}</span><h3>{clue.title}</h3><p>{clue.text}</p></article>)}{inContainment && <div className="response-status"><div className="agent-confirmed">✓ <span>{labConfirmed ? 'AGENTE CONFIRMADO' : 'HIPÓTESE ORIENTADORA'}</span><b>{mission.disease}</b></div><p>Para concluir, aplique três medidas e inclua as duas prioritárias.</p>{interventions.map((item) => <article className="evidence-card response-card" key={item.id}><span>{item.label}</span><h3>{item.title}</h3><p>{item.text}</p></article>)}</div>}</div>{logs.length > 0 && <div className="decision-feed"><span>ÚLTIMA DECISÃO</span><b>{logs[logs.length - 1].title}</b></div>}<div className="hypothesis"><span>{finished ? 'PRÓXIMO PASSO' : inContainment ? 'OBJETIVO' : 'PRÓXIMO PASSO'}</span><b>{finished ? 'Abra o debriefing para revisar a partida.' : inContainment ? (requiredComplete ? 'Prioridades aplicadas' : 'Priorize as medidas indicadas') : guidance}</b></div></aside> }

function Competencies({ logs, score }: { logs: Log[]; score: number }) { const has = (area: Area, tone?: Log['tone']) => logs.some((log) => log.area === area && (!tone || log.tone === tone)); const investigations = logs.filter((log) => log.area === 'investigacao').length; const entries = [['Raciocínio / diagnóstico', has('diagnostico', 'good') ? 'consistente' : 'em desenvolvimento', has('diagnostico', 'good') ? 'Sua defesa conectou hipóteses e evidências.' : 'Revise qual dado realmente separa os diferenciais.'], ['Investigação', investigations >= 2 ? 'consistente' : 'em desenvolvimento', investigations >= 2 ? `Você cruzou ${investigations} frentes de investigação antes de concluir.` : 'Cruze ao menos duas lentes antes de concluir.'], ['Conduta / tratamento', has('conduta', 'good') ? 'consistente' : 'atenção', has('conduta', 'good') ? 'Você protegeu pacientes enquanto investigava.' : 'Reavalie as prioridades de cuidado precoce.'], ['Controle / prevenção', has('controle', 'good') ? 'consistente' : 'em desenvolvimento', has('controle', 'good') ? 'Você aplicou uma medida prioritária no cenário.' : 'Conecte a resposta à forma de transmissão.'], ['Tempo de resposta', has('tempo', 'warn') ? 'atenção' : 'consistente', has('tempo', 'warn') ? 'A capacidade operacional ficou curta em um momento da partida.' : 'Você administrou ações e ciclos sem perda operacional registrada.']]; return <div className="competencies"><div className="score"><span>RESULTADO DA PARTIDA</span><b>{score} pts</b></div><span className="eyebrow">SEU DESEMPENHO POR ÁREA</span>{entries.map(([title, status, note]) => <article key={title}><div><b>{title}</b><span className={`competency-${status === 'consistente' ? 'good' : status === 'atenção' ? 'warn' : 'neutral'}`}>{status}</span></div><p>{note}</p></article>)}</div> }

function MissionSteps({ act }: { act: MissionAct }) {
  const steps = [{ id: 'proteger', icon: '🛟', label: '1. Proteja' }, { id: 'investigar', icon: '🔎', label: '2. Investigue' }, { id: 'decidir', icon: '🧩', label: '3. Decida' }, { id: 'controlar', icon: '🛡️', label: '4. Controle' }]
  const copy = act === 'proteger' ? ['Primeiro: proteja as pessoas', 'Use o cartão dourado da central. Depois a equipe entra em ação.'] : act === 'investigar' ? ['Agora: escolha um personagem', 'Cada pessoa traz uma peça diferente do quebra-cabeça.'] : act === 'decidir' ? ['Agora: conecte as pistas', 'Você já pode defender uma hipótese ou buscar mais uma evidência.'] : act === 'controlar' ? ['Agora: reduza o surto', 'Aplique três medidas, incluindo as duas prioritárias.'] : ['Missão concluída', 'Abra o debriefing para revisar suas escolhas.']
  return <section className={`mission-steps act-${act}`} aria-label={`Etapa atual: ${copy[0]}`}><div className="step-track">{steps.map((step) => <div key={step.id} className={`step-dot ${step.id === act ? 'active' : steps.findIndex((item) => item.id === step.id) < steps.findIndex((item) => item.id === act) ? 'done' : ''}`}><span>{step.icon}</span><b>{step.label}</b></div>)}</div><div className="act-callout"><div><span>PASSO A PASSO</span><b>{copy[0]}</b><p>{copy[1]}</p></div></div></section>
}

function GameGuide({ phase, urgentCare, clueCount, onDismiss }: { phase: Phase; urgentCare: boolean; clueCount: number; onDismiss: () => void }) {
  const step = !urgentCare
    ? { target: 'care-priority', title: 'Primeira prioridade', text: 'O cenário pede uma ação de proteção antes da confirmação. Acione a prioridade da central.', action: 'Mostrar prioridade' }
    : phase === 'investigation' && clueCount < 3
      ? { target: 'team-missions', title: 'Monte o quebra-cabeça', text: 'Agora escolha uma missão da equipe. Cada personagem entrega uma peça diferente do caso.', action: 'Ver missões' }
      : phase === 'investigation'
        ? { target: 'diagnosis-action', title: 'Hora de defender', text: 'Você já reuniu pistas suficientes. Conecte-as e apresente sua hipótese.', action: 'Defender hipótese' }
        : { target: 'response-actions', title: 'Controle o surto', text: 'Escolha medidas prioritárias para reduzir os casos e fechar a missão.', action: 'Ver medidas' }
  return <aside className={`game-guide game-guide-${step.target}`} aria-live="polite"><img src={ninaAssistant} alt="Nina, assistente da central" /><div className="game-guide-bubble"><button className="guide-close" onClick={onDismiss} aria-label="Fechar orientação da Nina">×</button><span>NINA · GUIA DA MISSÃO</span><h2>{step.title}</h2><p>{step.text}</p><b className="guide-arrow">↓</b></div></aside>
}

function Dialogs({ modal, mission, cycle, actions, cases, baseProjected, projected, event, eventOption, eventOptions, clues, diagnosis, rationale, diagnoses, rationaleOptions, error, reveal, outcome, score, reward, logs, onClose, onCloseReveal, onSelectDiagnosis, onSelectRationale, onConfirm, onShowEvent, onSelectEventOption, onAdvance, onFeedback, onReset, onCampaign }: { modal: Modal; mission: Mission; cycle: number; actions: number; cases: number; baseProjected: number; projected: number; event: CycleEvent; eventOption: CycleEvent['options'][number] | null; eventOptions: CycleEvent['options']; clues: number; diagnosis: string; rationale: string; diagnoses: string[]; rationaleOptions: Mission['diagnosticCheck']['options']; error: string; reveal: Reveal | null; outcome: string; score: number; reward: number; logs: Log[]; onClose: () => void; onCloseReveal: () => void; onSelectDiagnosis: (value: string) => void; onSelectRationale: (value: string) => void; onConfirm: () => void; onShowEvent: () => void; onSelectEventOption: (value: CycleEvent['options'][number]) => void; onAdvance: () => void; onFeedback: () => void; onReset: () => void; onCampaign: () => void }) {
  if (!modal) return null; const isClue = reveal && 'category' in reveal
  return <div className="modal-backdrop" role="presentation"><section className={`modal ${modal === 'briefing' ? 'briefing-modal' : ''} ${modal === 'diagnosis' ? 'diagnosis-modal' : ''} ${modal === 'reveal' ? 'reveal-modal' : ''} ${modal === 'win' || modal === 'lost' ? 'debrief-modal' : ''}`} role="dialog" aria-modal="true">
    {modal === 'briefing' && <><span className="modal-kicker">{mission.caseCode.toUpperCase()} · AGENTE OCULTO</span><div className="briefing-icon">⌁</div><h2>{mission.shortName}</h2><p>{mission.id === 1 ? 'Você coordena a central. Primeiro proteja, depois investigue e, por fim, defenda a hipótese.' : 'Cada ciclo tem três decisões. Escolha uma lente, leia o achado e monte o quadro de evidências antes de defender sua hipótese.'}</p><div className="briefing-case"><b>{mission.openingSyndrome}</b><p>{mission.brief}</p></div><div className="briefing-facts">{mission.initialData.map((item) => <span key={item.label}>{item.label}<b>{item.value}</b></span>)}</div><div className="modal-actions"><button className="primary" onClick={onClose}>Assumir caso</button></div></>}
    {modal === 'reveal' && reveal && <><span className="modal-kicker">{isClue ? `NOVA EVIDÊNCIA · ${(reveal as Clue).category.toUpperCase()}` : 'AÇÃO REGISTRADA'}</span><div className="reveal-symbol">{isClue ? '⌁' : '✓'}</div><h2>{reveal.title}</h2><p className="reveal-text">{reveal.text}</p>{!isClue && (reveal as Intervention).teachingNote && <div className="teaching-note"><span>POR QUE ESTA DECISÃO IMPORTA</span><p>{(reveal as Intervention).teachingNote}</p></div>}<div className="reveal-foot"><span>{actions} {actions === 1 ? 'decisão restante neste ciclo' : 'decisões restantes neste ciclo'}</span><b>{isClue ? 'Adicionado ao Quadro do caso' : 'Situação atualizada'}</b></div><div className="modal-actions"><button className="primary" onClick={onCloseReveal}>{actions === 0 ? 'Ver fechamento do ciclo' : 'Continuar'}</button></div></>}
    {modal === 'diagnosis' && <><span className="modal-kicker">DEFESA DE HIPÓTESE · {clues} EVIDÊNCIAS</span><h2>Qual hipótese explica melhor o conjunto?</h2><p>Escolha um diferencial e o dado com maior poder de separá-lo. Uma defesa precisa cruzar pelo menos duas lentes de investigação.</p><div className="diagnoses">{diagnoses.map((item) => <button className={diagnosis === item ? 'selected' : ''} onClick={() => onSelectDiagnosis(item)} key={item}>{item}</button>)}</div><div className="rationale"><span>{mission.diagnosticCheck.question}</span>{rationaleOptions.map((item) => <button key={item.id} className={rationale === item.id ? 'selected' : ''} onClick={() => onSelectRationale(item.id)}>{item.label}</button>)}</div><div className="modal-actions"><button className="secondary" onClick={onClose}>Voltar ao quadro</button><button className="primary" disabled={!diagnosis || !rationale} onClick={onConfirm}>Defender hipótese</button></div></>}
    {(modal === 'advance' || modal === 'complete') && <><span className="modal-kicker">{modal === 'complete' ? `CICLO ${cycle} CONCLUÍDO` : `FECHAR CICLO ${cycle}`}</span><h2>{modal === 'complete' ? 'Hora de observar a evolução do cenário.' : 'Abrir mão de decisões restantes?'}</h2><p>{modal === 'complete' ? 'As três decisões foram usadas. O próximo ciclo traz um sinal operacional para sua equipe.' : `Você ainda tem ${actions} decisão${actions > 1 ? 'ões' : ''}. Fechar agora reduz seu tempo de investigação.`}</p><div className="projection"><span>Casos ativos projetados</span><b>{cases} → {baseProjected}</b></div><div className="modal-actions">{modal === 'advance' && <button className="secondary" onClick={onClose}>Voltar às decisões</button>}<button className="primary" onClick={onShowEvent}>Ver situação do próximo ciclo</button></div></>}
    {modal === 'event' && <><span className="modal-kicker danger-text">SINAL OPERACIONAL · CICLO {cycle + 1}</span><div className="reveal-symbol event-symbol">!</div><h2>{event.title}</h2><p className="reveal-text">{event.text}</p><div className="event-options">{eventOptions.map((option) => <button className={eventOption?.id === option.id ? 'selected' : ''} onClick={() => onSelectEventOption(option)} key={option.id}><b>{option.label}</b><span>{option.text}</span><small>Impacto previsto: +{Math.round((option.pressureFactor - 1) * 100)}% nos casos ativos</small></button>)}</div>{eventOption && <><div className="teaching-note"><span>LEITURA DA ESCOLHA</span><p>{eventOption.teachingNote}</p></div><div className="projection"><span>Casos ativos no próximo ciclo</span><b>{cases} → {projected}</b></div></>}<div className="modal-actions"><button className="primary" disabled={!eventOption} onClick={onAdvance}>Iniciar ciclo {cycle + 1}</button></div></>}
    {modal === 'wrong' && <><span className="modal-kicker danger-text">DEFESA AINDA NÃO SUSTENTADA</span><h2>O caso avançou para o ciclo {cycle}.</h2><p>{error}</p><div className="modal-actions single"><button className="primary" onClick={onClose}>Voltar ao caso</button></div></>}
    {(modal === 'win' || modal === 'lost') && <><div className="trophy">{modal === 'win' ? '🏆' : '⚠️'}</div><span className={`modal-kicker ${modal === 'win' ? 'success-text' : 'danger-text'}`}>{modal === 'win' ? 'RESPOSTA CONCLUÍDA' : 'LIMITE CRÍTICO ATINGIDO'}</span><h2>{modal === 'win' ? `Debriefing: ${mission.disease}` : 'O caso exige uma nova tentativa'}</h2><p>{modal === 'win' ? mission.debrief : 'A pressão do cenário ultrapassou o limite antes de uma resposta adequada. Refaça o caso e compare suas decisões com o debriefing educativo.'}</p>{modal === 'win' && reward > 0 && <div className="reward-card"><span>RECOMPENSA DE PRIMEIRA CONCLUSÃO</span><b>+{reward} XP</b><small>+25 moedas para sua central</small></div>}{modal === 'win' && <Competencies logs={logs} score={score} />}<div className="learning-box"><span>APRENDIZADOS-CHAVE</span><ul>{mission.learningPoints.map((item) => <li key={item}>{item}</li>)}</ul><a href={mission.source.url} target="_blank" rel="noreferrer">{mission.source.label} ↗</a></div><div className="modal-actions result-actions"><button className="secondary" onClick={onFeedback}>Registrar opinião</button><button className="secondary" onClick={onCampaign}>Central de casos</button><button className="primary" onClick={onReset}>{modal === 'win' ? 'Reabrir caso' : 'Tentar novamente'}</button></div></>}
    {modal === 'feedback' && <FeedbackForm mission={mission} cycle={cycle} outcome={outcome} onClose={onClose} />}
  </section></div>
}

function FeedbackForm({ mission, cycle, outcome, onClose }: { mission: Mission; cycle: number; outcome: string; onClose: () => void }) { const [clarity, setClarity] = useState(0); const [engagement, setEngagement] = useState(0); const [reading, setReading] = useState(0); const [comment, setComment] = useState(''); const [saved, setSaved] = useState(false); const [copyState, setCopyState] = useState(''); const save = async () => { if (!clarity || !engagement || !reading) return; const entry = { mission: mission.caseCode, outcome, cycle, clarity, engagement, reading, comment: comment.trim(), createdAt: new Date().toISOString() }; try { const existing = JSON.parse(localStorage.getItem('missao-imunidade-feedback-v1') || '[]'); localStorage.setItem('missao-imunidade-feedback-v1', JSON.stringify([...existing, entry])); setSaved(true); try { await navigator.clipboard?.writeText(`Missão Imunidade — ${mission.caseCode}\nResultado: ${outcome}; ciclo: ${cycle}\nClareza: ${clarity}/5; decisões: ${engagement}/5; leitura: ${reading}/5\nComentário: ${entry.comment || '(sem comentário)'}`); setCopyState('Resumo copiado para compartilhar com a equipe.') } catch { setCopyState('Opinião salva neste navegador; a cópia automática não ficou disponível.') } } catch { setCopyState('Não foi possível salvar a opinião neste navegador.') } }; const scale = (label: string, value: number, setValue: (value: number) => void) => <div className="feedback-scale"><span>{label}</span><div>{[1, 2, 3, 4, 5].map((item) => <button type="button" aria-label={`${label}: ${item} de 5`} className={value === item ? 'selected' : ''} onClick={() => setValue(item)} key={item}>{item}</button>)}</div><small>1 = muito ruim · 5 = muito bom</small></div>; return <><span className="modal-kicker">TESTE DE EXPERIÊNCIA · OPINIÃO LOCAL</span><h2>Como foi este dossiê?</h2><p>Sua opinião fica somente neste navegador. Você decide se deseja compartilhar o resumo com a equipe.</p><div className="feedback-form">{scale('Entendi o ciclo e as consequências?', clarity, setClarity)}{scale('As escolhas pareceram significativas?', engagement, setEngagement)}{scale('A leitura e o celular ficaram confortáveis?', reading, setReading)}<label>O que confundiu, funcionou ou deveria mudar?<textarea value={comment} onChange={(event) => setComment(event.target.value)} maxLength={700} placeholder="Conte um momento específico do jogo." /></label></div>{(saved || copyState) && <p className="feedback-saved">{copyState || 'Opinião salva neste navegador.'}</p>}<div className="modal-actions"><button className="secondary" onClick={onClose}>Fechar</button><button className="primary" disabled={!clarity || !engagement || !reading || saved} onClick={save}>{saved ? 'Opinião registrada' : 'Salvar opinião'}</button></div></> }

function Profile({ initial, onSave }: { initial?: Student; onSave: (value: Student) => void }) { const [name, setName] = useState(initial?.name || ''); const [semester, setSemester] = useState(initial?.semester || '1'); const [focus, setFocus] = useState(initial?.focus || 'clinica'); const [error, setError] = useState(''); const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (name.trim().length < 2) { setError('Informe seu nome para personalizar a experiência.'); return } onSave({ name: name.trim(), semester, focus }) }; return <main className="profile-shell"><section className="profile-card"><div className="profile-mark">✦</div><span className="eyebrow">MISSÃO IMUNIDADE · AMBIENTE DE APRENDIZAGEM</span><h1>Antes do primeiro <em>plantão.</em></h1><p>Monte seu perfil de estudo. Ele adapta a saudação e destaca o eixo que você quer praticar.</p><form onSubmit={submit}><label>Como devemos chamar você?<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Seu nome" maxLength={60} /></label><div className="profile-row"><label>Semestre<select value={semester} onChange={(event) => setSemester(event.target.value)}>{Array.from({ length: 12 }, (_, i) => <option value={String(i + 1)} key={i}>{i + 1}º semestre</option>)}</select></label><label>Eixo de estudo<select value={focus} onChange={(event) => setFocus(event.target.value)}><option value="clinica">Raciocínio clínico</option><option value="microbiologia">Microbiologia</option><option value="epidemiologia">Epidemiologia</option><option value="saudeColetiva">Saúde coletiva</option></select></label></div>{error && <p className="form-error">{error}</p>}<button className="primary">Iniciar dossiês clínicos →</button></form><small>Essas informações ficam somente neste navegador.</small></section></main> }

function Campaign({ student, player, completed, testMode, tutorial, onTutorial, onCloseTutorial, onEdit, onStart }: { student: Student; player: Player; completed: number[]; testMode: boolean; tutorial: boolean; onTutorial: () => void; onCloseTutorial: () => void; onEdit: () => void; onStart: (mission: Mission, isDaily?: boolean) => void }) { const [mapMission, setMapMission] = useState(missions[0]); const first = student.name.split(' ')[0]; const today = localDay(); const dispatch = dailyDispatches[Number(today.split('-').join('')) % dailyDispatches.length]; const dailyMission = missions.find((mission) => mission.id === dispatch.missionId) || missions[0]; const claimed = player.dailyClaimed === today; return <main className="campaign-shell"><header className="campaign-header"><div className="brand"><span className="brand-mark">✦</span><span>MISSÃO <b>IMUNIDADE</b></span></div><div className="campaign-account"><PlayerHud player={player} /><button className="help-button" onClick={onTutorial}>Como jogar</button><button onClick={onEdit}>{first} · {student.semester}º semestre</button></div></header><section className="campaign-hero"><img src={worldMapImage} alt="Mapa-múndi ilustrativo" /><div className="campaign-map-focus" style={{ left: `${mapMission.mapPosition.x}%`, top: `${mapMission.mapPosition.y}%` }}><i /><span><b>{mapMission.caseCode} · {mapMission.shortName}</b>{mapMission.location}</span></div><div className="campaign-hero-copy"><span className="eyebrow">CENTRAL DE INVESTIGAÇÃO</span><h1>Olá, {first}.<br />Vamos ler o <em>surto.</em></h1><p>Assuma um dossiê, coordene a equipe e transforme evidência em resposta.</p><div className="campaign-progress"><b>{completed.length}/5</b><span>missões concluídas · foco: {focusLabels[student.focus]}</span></div></div></section><section className={`daily-dispatch ${claimed ? 'claimed' : ''}`}><div className="daily-orbit">✦</div><div><span>{dispatch.label} · MISSÃO DO DIA</span><h2>{dispatch.title}</h2><p>{dispatch.text}</p><b>Objetivo: {dispatch.objective}</b></div><div className="daily-reward"><span>{claimed ? 'RESGATADO HOJE' : 'RECOMPENSA DIÁRIA'}</span><strong>{claimed ? '✓ concluída' : '+80 XP · +15 moedas'}</strong><small>Sequência atual: {player.streak} dia{player.streak === 1 ? '' : 's'} 🔥</small><button onClick={() => onStart(dailyMission, !claimed)}>{claimed ? 'Revisar missão' : 'Aceitar alerta'} <b>→</b></button></div></section><section><div className="campaign-title"><div><span className="eyebrow">DOSSIÊS DISPONÍVEIS</span><h2>Onde sua equipe atua agora?</h2></div><p>Toque ou use Tab para localizar o dossiê no mapa e depois assumir o caso.</p></div><div className="mission-grid">{missions.map((mission, index) => { const unlocked = testMode || index === 0 || completed.includes(missions[index - 1].id); const done = completed.includes(mission.id); return <article className={`mission-card ${!unlocked ? 'locked' : ''} ${done ? 'done' : ''} ${mapMission.id === mission.id ? 'map-active' : ''}`} key={mission.id} onMouseEnter={() => setMapMission(mission)} onFocus={() => setMapMission(mission)} onClick={() => setMapMission(mission)}><span className="mission-number">{done ? '✓' : `0${mission.id}`}</span><div className="mission-card-icon">{['🌊', '🦟', '🧭', '🏥', '🧫'][index]}</div><span>{mission.region}</span><h3>{mission.shortName}</h3><p>{mission.openingSyndrome}</p><button disabled={!unlocked} onClick={(event) => { event.stopPropagation(); onStart(mission) }}>{unlocked ? (done ? 'Reabrir dossiê' : 'Assumir caso') : 'Dossiê bloqueado'} <b>→</b></button></article> })}</div></section>{tutorial && <Tutorial onClose={onCloseTutorial} />}</main> }

function Tutorial({ onClose }: { onClose: () => void }) { return <div className="modal-backdrop tutorial-backdrop"><section className="tutorial tutorial-complete" role="dialog" aria-modal="true" aria-labelledby="tutorial-title"><span className="modal-kicker">GUIA RÁPIDO · COMO JOGAR</span><h2 id="tutorial-title">Comande uma resposta, não um questionário.</h2><p>Você toma decisões em uma central de resposta. A meta é proteger pessoas e explicar por que uma hipótese orienta o plano.</p><div className="tutorial-steps tutorial-short"><article><b>1</b><div><h3>Leia o chamado</h3><p>Veja o cenário e os indicadores. Casos, atendimento, prazo e recursos contam histórias diferentes.</p></div></article><article><b>2</b><div><h3>Acione a equipe</h3><p>Cada personagem entrega uma lente. Exames custam recursos e podem chegar no próximo ciclo.</p></div></article><article><b>3</b><div><h3>Cuide e investigue</h3><p>Uma urgência pode pedir ação antes da confirmação. Depois, conecte clínica, exposição, vigilância e laboratório.</p></div></article><article><b>4</b><div><h3>Revise sua partida</h3><p>O debriefing mostra o que suas próprias decisões revelam sobre investigação, conduta e controle.</p></div></article></div><div className="tutorial-tip"><b>Dica:</b> informações isoladas raramente bastam. Use mais de uma lente antes de defender uma hipótese.</div><div className="modal-actions"><button className="primary" onClick={onClose}>Entrar na central</button></div></section></div> }

createRoot(document.getElementById('root')!).render(<App />)
